INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "黎利", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "黎利在交阯起兵。", "biography": null, "status": "draft", "id": "c3cb3b52-845e-5798-86eb-c3dfdd072dcd"}, {"name": "柳升", "aliases": ["安远侯"], "era": "明", "birth_year": null, "death_year": null, "description": "柳升以安远侯身份率领大营。", "biography": null, "status": "draft", "id": "14f79103-5514-5b8a-b46f-74887204ab53"}, {"name": "郑亨", "aliases": ["武安侯"], "era": "明", "birth_year": null, "death_year": null, "description": "郑亨以武安侯身份率领中军。", "biography": null, "status": "draft", "id": "c500cb31-5132-5a9b-8600-28aa5c7f9ee8"}, {"name": "张辅", "aliases": ["张文弼"], "era": "明", "birth_year": null, "death_year": null, "description": "张辅率军在爱子江交战。", "biography": null, "status": "draft", "id": "ef0d049d-1c37-5697-84d4-4274dfac2d2d"}, {"name": "李安（明代安平伯）", "aliases": ["安平伯"], "era": "明", "birth_year": null, "death_year": null, "description": "李安（明代安平伯）与张辅同领左掖。", "biography": null, "status": "draft", "id": "351483eb-71df-5a0d-9ec4-d88888e27535"}, {"name": "王通（明代成山侯）", "aliases": ["成山侯"], "era": "明", "birth_year": null, "death_year": null, "description": "王通赴陕西赈济饥民。", "biography": null, "status": "draft", "id": "f94e24e9-3278-51e4-895d-513be2a33e0d"}, {"name": "陈懋", "aliases": ["宁阳侯"], "era": "明", "birth_year": null, "death_year": null, "description": "陈懋以宁阳侯身份巡边阅兵。", "biography": null, "status": "draft", "id": "e5696099-627f-57a5-b989-87e71d1b2e68"}, {"name": "李时勉", "aliases": ["李懋"], "era": "明", "birth_year": null, "death_year": null, "description": "李时勉以侍读身份被下狱。", "biography": null, "status": "draft", "id": "c925d68f-aef6-5e23-93cb-cd7a19e52416"}, {"name": "朱高炽", "aliases": ["明仁宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明仁宗，永樂22年（1424年）八月，朱高炽即皇帝位。", "biography": null, "status": "draft", "id": "2dded14d-7183-56b5-9029-ca93826c1e80"}, {"name": "阿鲁台", "aliases": ["和宁王"], "era": "明", "birth_year": null, "death_year": null, "description": "阿鲁台受封和宁王。", "biography": null, "status": "draft", "id": "fd6d854f-724b-5621-91d3-593e412f448b"}, {"name": "也先土干", "aliases": ["忠勇王", "金忠（忠勇王）"], "era": "明", "birth_year": null, "death_year": null, "description": "也先土干向明廷归降并获封赐名。", "biography": null, "status": "draft", "id": "af25e7f1-fe4b-51e9-8c57-075823d453d5"}, {"name": "郑和", "aliases": ["鄭和"], "era": "明", "birth_year": null, "death_year": null, "description": "明代中官。本纪载其于永乐三年率舟师出使西洋各国。", "biography": null, "status": "draft", "id": "9a24d146-cea1-5746-85e4-479becda6195"}, {"name": "吕震（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐3年（年号对照1405年）九月，吕震出任刑部尚书。", "biography": null, "status": "draft", "id": "d58bc9ab-d97e-592e-909f-284f788a262a"}, {"name": "杨荣", "aliases": ["楊榮"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，杨荣以翰林修撰身份入直文渊阁。", "biography": null, "status": "draft", "id": "3da8dec2-a076-58ad-bf6e-5271a8173343"}, {"name": "金幼孜", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，金幼孜以翰林检讨身份入直文渊阁。", "biography": null, "status": "draft", "id": "01f8c39e-a2e9-5539-9e26-8926e64fc703"}, {"name": "朱瞻基", "aliases": ["明宣宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宣宗，洪熙元年（1425年）六月，朱瞻基即皇帝位。", "biography": null, "status": "draft", "id": "888fc961-674c-52bf-b645-1351d5637434"}, {"name": "李远（明初安平侯）", "aliases": ["安平侯"], "era": "明", "birth_year": null, "death_year": null, "description": "李远（明初安平侯）受封安平侯，为李安之父。", "biography": null, "status": "draft", "id": "80e172c4-9291-53d1-ad19-10b745337a74"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明成祖在南郊祭祀天地", "description": "永乐二十一年正月乙未，明成祖朱棣在南郊举行祭祀天地的大典。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年正月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "db5de3e8-0d02-5597-aec5-fc17ca321bd7"}, {"title": "陈智在车来追击并击败黎利所部", "description": "永乐二十一年正月癸卯，交阯参将荣昌伯陈智在车来追击黎利，将其所部击败。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年正月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5efe1e1a-c9dd-58c9-82b8-a7b7eb065175"}, {"title": "鹿荣出兵平定柳州一带反抗", "description": "永乐二十一年二月己巳，都指挥使鹿荣出兵征讨柳州一带反抗明廷的当地居民，本纪记载战事平息。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年二月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "353101f1-6cd1-5c68-9abe-767bf271e720"}, {"title": "王愈等误杀四名无罪者获罪被处死", "description": "永乐二十一年三月庚子，御史王愈等会审处决重囚时，误杀四名无罪者。本纪记王愈等因此被判处死刑。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年三月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33b6eaea-ef4a-563f-b47c-efd1b546b4eb"}, {"title": "明廷减免开封等地的水灾田租", "description": "永乐二十一年五月癸未，朝廷豁免开封、南阳、卫辉、凤阳等地上年受水灾所涉田租。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年五月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ecce635f-4b89-5fd0-859f-35b3899b21fd"}, {"title": "孟贤等被以谋逆罪处死", "description": "永乐二十一年五月己丑，常山护卫指挥孟贤等人因被认定谋逆而遭处死。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年五月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aeea9574-20ed-5151-8c4e-81518de73682"}, {"title": "六月初一发生日食", "description": "永乐二十一年六月初一，发生日食。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年六月庚戌朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d5938b99-9b1e-5370-b2ef-28bb3ca1da78"}, {"title": "明成祖再次亲征阿鲁台，部署各部将领", "description": "永乐二十一年七月戊戌，明成祖朱棣再次亲自领兵征讨阿鲁台，任命中军、左右哨、左右掖及前锋诸将。张辅与安平伯李安领左掖。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年七月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4389c939-935e-5c3e-a18e-2ff2127a502b"}, {"title": "李时勉获释并恢复官职", "description": "永乐二十一年七月庚子，明廷释放李时勉，并恢复他的官职。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年七月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f850068f-66cb-584c-893f-e3fdfb157ea9"}, {"title": "皇太子朱高炽监国", "description": "永乐二十一年七月辛丑，明成祖出征期间，皇太子朱高炽监理国政。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年七月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b78fd552-4e58-51be-854f-3f15e2110450"}, {"title": "明成祖从京师发兵", "description": "永乐二十一年七月壬寅，明成祖朱棣率军离开京师。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年七月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "51e20ad4-cdff-5175-b29c-16fdd3cadc58"}, {"title": "明成祖到宣府，命居庸关守将停止官署进奉", "description": "永乐二十一年七月戊申，明成祖朱棣到达宣府，命居庸关守将制止各官署进奉。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年七月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7c7f202e-20cc-55cf-a04a-d49713ca627b"}, {"title": "明成祖检阅北征军", "description": "永乐二十一年八月己酉，明成祖朱棣在北征期间检阅军队。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年八月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "11e63f1c-4cfe-5424-a6c9-af9c0b72d836"}, {"title": "明军封堵黑峪、长安岭等处边境隘口", "description": "永乐二十一年八月庚申，明军封堵黑峪、长安岭等边境险要通道。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年八月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c2fe9ade-f8cd-5b43-94bc-c3fece8b854a"}, {"title": "皇太子免除两京及山东的水灾田租", "description": "永乐二十一年八月丁丑，监国的皇太子朱高炽豁免两京、山东受水灾郡县的田租。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年八月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "393b9c11-5d7c-57fa-adb0-31175780a37a"}, {"title": "明成祖所率北征军行至西阳河", "description": "永乐二十一年九月戊子，明成祖率领的北征军到达西阳河。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年九月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "016c035c-7a83-5a56-9e32-02cd3a6eb248"}, {"title": "北征军获悉阿鲁台战败后停止前进", "description": "永乐二十一年九月癸巳，明军得到阿鲁台败于瓦剌、部众溃散的消息，于是就地驻扎。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年九月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bd37ebf9-6eef-50bc-b200-84fc6d0c9127"}, {"title": "也先土干率部归降，受封忠勇王并获赐姓名金忠", "description": "永乐二十一年十月甲寅，明军行至上庄堡。迤北王子也先土干率部归降，明廷随后将他封为忠勇王，并赐姓名金忠。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年十月甲寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8ad5bbc7-b2c0-55e4-8b4a-9a1b0e8a8960"}, {"title": "明成祖率北征军班师", "description": "永乐二十一年十月庚午，明成祖朱棣率北征军返回。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年十月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "258fccc5-c335-574f-8772-0134b95edc06"}, {"title": "北征的明成祖回到京师", "description": "永乐二十一年十一月甲申，明成祖朱棣北征后返回京师。", "start_year": 1423, "end_year": 1423, "time_original": "永乐二十一年十一月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4390bd5b-c129-595d-9418-fb02fc233485"}, {"title": "锡兰山王来朝，本纪另记多地入贡", "description": "永乐二十一年，锡兰山王来朝，又派使者入贡。占城、古里、忽鲁谟斯等地亦有入贡记录。 按原历纪年，事情发生在公元1423至1424年之间。", "start_year": null, "end_year": null, "time_original": "永乐二十一年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4d4edcc6-84ef-5f71-9760-02d29e3e3b7e"}, {"title": "阿鲁台进犯大同、开平，明廷商议北征", "description": "永乐二十二年正月甲申，阿鲁台率部进犯大同、开平。朝廷命群臣商议北征，并命边地将领整备军队、等候命令。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年正月甲申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "96f2bb11-e1e7-5f31-9d9f-e0c85cf987bb"}, {"title": "明廷调各地兵马会集北京及宣府", "description": "永乐二十二年正月丙戌，朝廷调山西等五都司及西宁等各卫的兵力，定于三月在北京和宣府会集。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年正月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a36f15c5-c2ec-5942-a2f1-59f0808c5be5"}, {"title": "明成祖在南郊祭祀天地", "description": "永乐二十二年正月戊子，明成祖朱棣在南郊祭祀天地。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年正月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7eca2e2b-9645-55e1-af4b-4a4f6962a542"}, {"title": "本纪记郑和再度出使西洋", "description": "永乐二十二年正月癸巳，《明史》本纪记郑和再次出使西洋。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年正月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eb9fc47b-b295-5ef4-b94a-1bb334efd6da"}, {"title": "明成祖阅兵并布置北征各部", "description": "永乐二十二年三月戊寅，明成祖朱棣阅兵，向将领宣布亲征，指定柳升等将领分辖中军、左右掖、左右哨和前锋。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年三月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "662192d5-2079-5f76-8fe4-6f8a31e7c24b"}, {"title": "朝廷授邢宽等人不同等第的进士资格", "description": "永乐二十二年三月己卯，明廷授予邢宽等人不同等第的进士资格。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年三月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f3bc46c2-1c3c-5c6e-84f7-797babb1e165"}, {"title": "皇太子朱高炽奉命监国", "description": "永乐二十二年四月戊申，皇太子朱高炽负责监理国政。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年四月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "52a87b9c-9654-59ad-9a84-c9def40a9d8f"}, {"title": "明成祖从京师领兵北征", "description": "永乐二十二年四月己酉，明成祖朱棣率军自京师启程。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年四月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "28f49758-c4ee-513a-8d6b-f0741a3db7f9"}, {"title": "明军行至隰宁，获报后向答兰纳木儿河进兵", "description": "永乐二十二年四月庚午，明军到达隰宁。探子报告阿鲁台向答兰纳木儿河撤走，明军随即向该方向进兵。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年四月庚午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e37ae007-b98e-5847-925a-5fb5803bc61a"}, {"title": "明军到开平，派使者招谕阿鲁台各部", "description": "永乐二十二年五月己卯，明军行至开平，派使者前往招谕阿鲁台各部。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年五月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "303932c3-5fea-540e-aba7-10e65318ecac"}, {"title": "明军掩埋路边遗骸", "description": "永乐二十二年五月乙酉，明军掩埋途中发现的遗骸。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年五月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "89d09553-4487-5eb9-808d-82295a648583"}, {"title": "明成祖在应昌宴群臣，命人唱《太祖御制词》", "description": "永乐二十二年五月丁酉，明成祖朱棣在应昌设宴招待群臣，命宦官唱明太祖所作的五章词。他说这是先帝对后人的告诫，即使出征在外也不能忘记。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年五月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ee111ebf-4495-53f5-99a3-5134ccdd01e8"}, {"title": "明成祖在威远州宴群臣并命人唱自作之词", "description": "永乐二十二年五月己亥，明成祖朱棣行至威远州，再次设宴招待群臣，并命宦官唱他亲作的五章词。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年五月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c61d3444-a1aa-5298-8ace-3947c7f4732f"}, {"title": "皇太子免除广平等水灾地区田租", "description": "永乐二十二年五月，监国的皇太子朱高炽命免收广平、顺德、扬州及湖广、河南受水灾郡县的田租。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "87a53641-e7c1-596c-a477-6757c5eb18a8"}, {"title": "明军到答兰纳木儿河搜寻对手未果", "description": "永乐二十二年六月庚申，北征前锋抵达答兰纳木儿河，未发现对手。张辅等奉命搜索附近山谷，没有找到，军队进驻河边。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年六月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ae022253-4550-508d-b0b5-a9a024a88453"}, {"title": "陈懋等到白邙山后因粮尽返回", "description": "永乐二十二年六月癸亥，陈懋等率部到达白邙山，因粮食耗尽而返回。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年六月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f3b47a23-7c1e-5648-bcb5-deed20295685"}, {"title": "明军班师，郑亨等率步军到开平会合", "description": "永乐二十二年六月甲子，明成祖下令班师，命郑亨等率步兵向西，到开平会合。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年六月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a3bd3055-7477-58ab-9522-26ff1bf23012"}, {"title": "南京夜间发生地震", "description": "永乐二十二年六月壬申夜，南京发生地震。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年六月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7dccc345-a303-535d-8c77-04ecdfaf2e3e"}, {"title": "北征回师途中在清水源崖刻石", "description": "永乐二十二年七月庚辰，北征回师途中的朝廷在清水源一处崖壁刻石留记。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年七月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8468f6ac-6372-51af-afb0-3489b567dcda"}, {"title": "吕震奉命将班师消息告知皇太子", "description": "永乐二十二年七月戊子，明成祖派吕震向皇太子通报班师消息，并向天下颁诏。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年七月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8987b91c-71bc-5710-803c-de94d41f70d5"}, {"title": "明成祖行至苍崖戍时患病", "description": "永乐二十二年七月己丑，明成祖朱棣带军到达苍崖戍时患病。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年七月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d1586185-44ec-58cc-8c63-aae31618162b"}, {"title": "明成祖在榆木川病重，遗诏由皇太子继位", "description": "永乐二十二年七月庚寅，明成祖朱棣至榆木川，病势转重。他留下遗诏，由皇太子朱高炽继承皇位，丧礼依明太祖遗制办理。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年七月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "63e7e607-17b0-5631-86b4-3aaa9ea5cb45"}, {"title": "明成祖朱棣在榆木川去世", "description": "永乐二十二年七月辛卯，明成祖朱棣在榆木川去世，本纪记其享年六十五。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年七月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d85ed957-25d7-5fc1-86b1-f3e0ed0ae4d7"}, {"title": "明成祖去世后，马云与杨荣、金幼孜商定暂缓发丧", "description": "永乐二十二年七月，明成祖去世后，太监马云与大学士杨荣、金幼孜商议。因随征部队都在外地，他们暂缓公开发布丧讯，沿途礼仪照常。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "415b2e90-c2a6-5ad6-8816-90d6ed2d0a1b"}, {"title": "杨荣与海寿赴皇太子处报丧", "description": "永乐二十二年七月壬辰，杨荣和御马监少监海寿启程，向皇太子报告明成祖的死讯。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年七月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3113c76d-536f-51de-b0e2-924b5ad86174"}, {"title": "北征回军到武平镇，郑亨步军来会", "description": "永乐二十二年七月壬寅，北征回军行至武平镇，郑亨率领的步军来会合。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年七月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "58602783-ae77-529b-8a7a-bb3afbdd4d6f"}, {"title": "杨荣等抵京，皇太子遣皇太孙往开平迎灵", "description": "永乐二十二年八月甲辰，杨荣等到达京师。皇太子朱高炽当天派皇太孙朱瞻基前往开平迎接明成祖的灵柩。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e8d82b3-281f-50f4-897e-e2beb61882ab"}, {"title": "皇太孙到鵰鹗谷军中宣布明成祖死讯", "description": "永乐二十二年八月己酉，回军行至鵰鹗谷。皇太孙朱瞻基赶到军中，公开发布明成祖的丧讯。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "529d2e6f-2c2b-5b6a-888e-965fea8b090e"}, {"title": "皇太子迎明成祖灵柩入仁智殿", "description": "永乐二十二年八月壬子，明成祖灵柩到达京郊，皇太子朱高炽将其迎入仁智殿，再行殓礼，并纳入专用棺木。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e62bb125-c553-532a-b830-56781b2779f5"}, {"title": "朱棣被追号文皇帝、庙号太宗", "description": "永乐二十二年九月壬午，明廷为朱棣上尊谥文皇帝，定庙号为太宗。本纪随后记他安葬在长陵。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9bdd6d02-ed54-5035-b0fc-2e5edd3a5c4c"}, {"title": "明廷改朱棣庙号为成祖", "description": "嘉靖十七年九月，明廷重新拟定朱棣的尊谥，改其庙号为成祖。", "start_year": 1538, "end_year": 1538, "time_original": "嘉靖十七年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2e6b19f4-e207-5850-af3d-efffb174457f"}, {"title": "吕震请举行封禅，明成祖拒绝", "description": "永乐十四年四月壬申，礼部尚书吕震请求举行封禅礼。明成祖朱棣说，各地仍有水灾、旱灾和疫病，不能自称太平，六经也没有封禅的记载，因此没有采纳。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年四月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dba0d434-240e-51fd-bc5f-289e09d9ed24"}, {"title": "纪纲获罪被处死", "description": "永乐十四年七月乙巳，主管锦衣卫事务的纪纲获罪被处死。本纪称他为锦衣卫指挥使，卷末校记引《太宗实录》作「掌锦衣卫事都指挥佥事」。", "start_year": 1416, "end_year": 1416, "time_original": "永乐十四年七月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1333afd0-7a2e-54a1-9333-85e9eade5ded"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

